const soru = $input.first().json[0];
const body = $('Webhook - Cevap Gönder').first().json.body;

const dogru = soru.dogru_cevap === body.verilen_cevap;
const puan = dogru ? soru.zorluk_puani : 0;

return [{ json: {
  kullanici_id: body.kullanici_id,
  soru_id: body.soru_id,
  ders: body.ders || soru.ders,
  konu: body.konu || soru.konu,
  verilen_cevap: body.verilen_cevap,
  dogru_cevap: soru.dogru_cevap,
  dogru_mu: dogru,
  puan: puan,
  sure_saniye: body.sure_saniye || 0,
  zorluk_puani: soru.zorluk_puani,
  tarih: new Date().toISOString()
}}];

const cevaplar = $input.first().json;
const toplam = cevaplar.length;
const dogru = cevaplar.filter(c => c.dogru_mu).length;
const yanlis = toplam - dogru;
const basariOrani = toplam > 0 ? Math.round((dogru / toplam) * 100) : 0;
const toplamPuan = cevaplar.reduce((s, c) => s + (c.puan || 0), 0);

const anlasilan = $('Cevabı Değerlendir').first().json;

// GPT ile zayıf konu analizi (her 10 soruda bir)
const analiz_yap = toplam > 0 && toplam % 10 === 0;

return [{ json: {
  kullanici_id: anlasilan.kullanici_id,
  ders: anlasilan.ders,
  toplam_soru: toplam,
  dogru_sayi: dogru,
  yanlis_sayi: yanlis,
  basari_orani: basariOrani,
  toplam_puan: toplamPuan,
  son_cevap_dogru: anlasilan.dogru_mu,
  analiz_yap: analiz_yap,
  guncelleme_tarihi: new Date().toISOString()
}}];

